css('slope','''R{display:flex;flex-direction:column;gap:var(--gap);padding:var(--gap-lg);position:relative}R>.heads{display:flex;justify-content:space-between;align-items:center;font-size:var(--type-18)}R>.pair{flex:1;position:relative;display:grid;grid-template-columns:1fr auto 1fr;gap:var(--gap);align-items:center;border-bottom:var(--stroke) solid var(--n-2);min-height:0}R>.pair>.name{grid-column:2;font-size:var(--type-18);text-align:center;z-index:1;background:var(--page);padding:var(--gap-sm);border-radius:999px}R>.pair>.a{grid-column:1;grid-row:1;justify-self:start;font-size:var(--type-24)}R>.pair>.b{grid-column:3;grid-row:1;justify-self:end;font-size:var(--type-24);color:var(--a1)}R>.pair:before{content:'';position:absolute;left:0;right:0;top:50%;height:var(--stroke);background:var(--a1-3-soft);transform:rotate(calc((var(--a) - var(--b))*.15deg))}R>.pair.on:before{height:2px;background:var(--a1)}R.dumbbell>.pair:before{left:calc(var(--a)/var(--max)*70%);right:calc((1 - var(--b)/var(--max))*70%);transform:none;border-radius:999px;height:4px}''')
css('roadmap','''R{display:flex;flex-direction:column;gap:var(--gap-sm);padding:var(--gap-sm)}R>.heads{display:grid;grid-template-columns:repeat(var(--cols),minmax(0,1fr));padding-left:18%;font-size:var(--type-18);text-align:center;gap:var(--gap-sm)}R>.lane{position:relative;display:grid;grid-template-columns:repeat(var(--cols),minmax(0,1fr));grid-auto-rows:minmax(0,1fr);margin-left:18%;flex:1;min-height:0;border-bottom:var(--stroke) solid var(--n-3);gap:var(--gap-sm)}R>.lane>.name{position:absolute;right:calc(100% + var(--gap));top:35%;font-size:var(--type-18);width:19%;text-align:right}R .bar{grid-column:calc(var(--from) + 1)/calc(var(--to) + 1);display:flex;align-items:center;justify-content:center;padding:var(--gap-sm);border-radius:999px;background:var(--a1-1-soft);color:var(--ink);font-size:var(--type-18);text-align:center}R .bar.on{background:var(--a1);color:var(--a1-on)}R .mile{position:absolute;left:calc(var(--at)/var(--cols)*100%);top:0;bottom:0;width:2px;background:var(--a1)}R .mile>span{position:absolute;bottom:100%;font-size:var(--type-14);white-space:nowrap}''')
css('concentric','''R{display:flex;align-items:flex-end;justify-content:center;padding:var(--gap-sm);position:relative}R>.ring{position:absolute;left:8%;right:8%;bottom:var(--gap-sm);height:92%;border-radius:50% 50% 0 0;background:var(--n-2);padding:var(--pad);text-align:center}R>.ring:nth-child(2){left:20%;right:20%;height:65%;background:var(--a1-2-soft)}R>.ring:nth-child(3){left:32%;right:32%;height:39%;background:var(--a1);color:var(--a1-on)}R>.ring:nth-child(4){left:40%;right:40%;height:22%;background:var(--a1-7);color:var(--page)}R .name{font-size:var(--type-22)}R .fig{font-size:var(--type-32)}R .note{font-size:var(--type-16)}''')
css('journey','''R{display:flex;gap:var(--gap);align-items:stretch;padding:var(--gap-lg) var(--gap-sm)}R>.stage{flex:1;min-width:0;position:relative;display:flex;flex-direction:column;justify-content:flex-end;gap:var(--gap-sm);padding:var(--gap);background:var(--page);border-radius:var(--radius)}R>.stage:before{content:'';position:absolute;left:45%;bottom:calc(45% + var(--mood)*.4%);width:14px;height:14px;background:var(--a1);border-radius:50%}R>.stage:not(:last-child):after{content:'';position:absolute;left:50%;width:calc(100% + var(--gap));bottom:calc(45% + var(--mood)*.4%);height:2px;background:var(--a1-3-soft);transform-origin:left;transform:rotate(calc((var(--mood) - var(--next))*.25deg))}R>.stage.on{background:var(--a1-1-soft)}R .name{font-size:var(--type-22)}R .note{font-size:var(--type-16)}R .pain{font-size:var(--type-14);color:var(--bad);margin-top:var(--gap-sm)}''')
css('mindmap','''R{display:grid;grid-template-columns:1fr 1.2fr 1fr;grid-template-rows:repeat(3,minmax(0,1fr));gap:var(--gap);padding:var(--gap-sm);align-items:center}R>.core{grid-column:2;grid-row:1/4;border-radius:50%;aspect-ratio:1;display:flex;align-items:center;justify-content:center;text-align:center;padding:var(--pad);background:var(--a1);color:var(--a1-on)}R>.branch{display:flex;flex-direction:column;gap:var(--gap-sm);position:relative;padding:var(--gap-sm);background:var(--page);border-radius:var(--radius)}R>.branch:nth-child(even){grid-column:1}R>.branch:nth-child(odd){grid-column:3}R>.branch:before{content:'';position:absolute;right:calc(var(--gap)*-1);width:var(--gap);top:50%;height:var(--stroke);background:var(--a1-3-soft)}R>.branch:nth-child(odd):before{left:calc(var(--gap)*-1);right:auto}R>.branch.on{background:var(--a1-1-soft)}R .leaf{font-size:var(--type-16);color:var(--n-7)}''')
css('decision-tree','''R{display:flex;flex-direction:column;justify-content:center;gap:var(--gap-lg);padding:var(--gap-sm)}R .q,R .end{display:flex;align-items:center;justify-content:center;padding:var(--gap);background:var(--page);border-radius:var(--radius);position:relative;text-align:center}R>.q{background:var(--a1);color:var(--a1-on);align-self:center;padding:var(--gap) var(--gap-lg)}R .opts{display:flex;gap:var(--gap);min-width:0}R .opt{flex:1;display:flex;flex-direction:column;gap:var(--gap);min-width:0;position:relative}R .opt:before{content:'';position:absolute;left:50%;top:calc(var(--gap-lg)*-1);height:var(--gap-lg);width:var(--stroke);background:var(--a1-3-soft)}R .cond{font-size:var(--type-16);color:var(--a1);text-align:center}R .end.on{background:var(--a1);color:var(--a1-on)}R .name{font-size:var(--type-22)}''')
css('balance','''R{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr auto;gap:var(--gap-lg);padding:var(--pad);position:relative}R:before{content:'';position:absolute;left:12%;right:12%;bottom:15%;height:4px;background:var(--a1);transform:rotate(calc(var(--tilt)*.08deg));border-radius:999px}R>.pan{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:var(--gap);padding:var(--pad);border-radius:var(--radius);background:var(--page);position:relative}R>.pan.on{background:var(--a1-1-soft)}R>.pan>.name{font-size:var(--type-28);color:var(--a1)}R>.pan .item{font-size:var(--type-18);text-align:center}R>.fulcrum{grid-column:1/-1;justify-self:center;position:relative;padding-top:var(--gap-lg);font-size:var(--type-20);text-align:center}R>.fulcrum:before{content:'';position:absolute;top:0;left:calc(50% - 22px);width:44px;height:35px;background:var(--a1);clip-path:polygon(50% 0,100% 100%,0 100%)}''')
css('matrix-nine','''R{display:grid;grid-template-columns:var(--gap-lg) repeat(3,minmax(0,1fr));grid-template-rows:repeat(3,minmax(0,1fr)) var(--gap-lg);gap:var(--gap-sm);padding:var(--gap-sm)}R>.axis-x{grid-column:2/5;grid-row:4;display:flex;justify-content:space-around;align-items:center;font-size:var(--type-16)}R>.axis-y{grid-column:1;grid-row:1/4;display:flex;flex-direction:column-reverse;justify-content:space-around;font-size:var(--type-16)}R>.cell{display:flex;flex-direction:column;justify-content:center;gap:var(--gap-sm);background:var(--page);border-radius:var(--radius-sm);padding:var(--gap)}R>.cell.on{background:var(--a1);color:var(--a1-on)}R .name{font-size:var(--type-22)}R .note{font-size:var(--type-16)}''')
for i in range(9):css('matrix-nine',f'R>.cell:nth-child({i+1} of .cell){{grid-column:{i%3+2};grid-row:{i//3+1};}}')
css('positioning','''R{position:relative;border-radius:var(--radius);background:var(--page);padding:var(--gap-lg);margin:var(--gap)}R:before{content:'';position:absolute;left:var(--gap-lg);right:var(--gap-lg);top:50%;border-top:var(--stroke) dashed var(--n-5)}R:after{content:'';position:absolute;top:var(--gap-lg);bottom:var(--gap-lg);left:50%;border-left:var(--stroke) dashed var(--n-5)}R>.axis-x{position:absolute;bottom:0;left:var(--gap);right:var(--gap);display:flex;justify-content:space-between;font-size:var(--type-16)}R>.axis-y{position:absolute;left:0;top:var(--gap);bottom:var(--gap);display:flex;flex-direction:column-reverse;justify-content:space-between;font-size:var(--type-16)}R>.mark{position:absolute;left:calc(10% + var(--x)*.8%);bottom:calc(10% + var(--y)*.8%);transform:translate(-50%,50%);width:80px;height:80px;border-radius:50%;background:var(--n-2);display:flex;align-items:center;justify-content:center;text-align:center;z-index:1;padding:var(--gap-sm)}R>.mark.on{background:var(--a1-1-soft);color:var(--a1);width:116px;height:116px}R>.mark .name{font-size:var(--type-18)}R>.mark .seat{width:70px;height:70px}''')
css('network','''R{position:relative;margin:var(--gap-lg)}R>.node{position:absolute;left:calc(var(--x)*1%);top:calc(var(--y)*1%);transform:translate(-50%,-50%);width:92px;height:92px;border-radius:50%;padding:var(--gap-sm);background:var(--page);border:var(--stroke) solid var(--a1-3-soft);display:flex;align-items:center;justify-content:center;text-align:center;z-index:1}R>.node.on{background:var(--a1);color:var(--a1-on)}R>.node .name{font-size:var(--type-18)}R>.link{position:absolute;left:calc(var(--x1)*1%);top:calc(var(--y1)*1%);width:calc(hypot((var(--x2) - var(--x1))*1cqw,(var(--y2) - var(--y1))*1cqh));height:var(--stroke);transform-origin:left;transform:rotate(atan2((var(--y2) - var(--y1))*1cqh,(var(--x2) - var(--x1))*1cqw));background:var(--n-4)}R>.link.strong{background:var(--a1);height:2px}''')
css('code','''R{display:flex;flex-direction:column;gap:var(--gap);padding:var(--pad);border-radius:var(--radius);background:var(--n-1);font-family:var(--font-body);overflow:hidden}R>.name{font-size:var(--type-20);color:var(--a1)}R>.lines{flex:1;min-height:0;display:flex;flex-direction:column;justify-content:center;counter-reset:code;gap:calc(var(--gap-sm)/3)}R>.lines>p{white-space:pre-wrap;overflow-wrap:anywhere;font-size:var(--type-18);line-height:var(--body-line);font-weight:var(--body-weight)}R.numbered>.lines>p{counter-increment:code;padding-left:var(--gap-lg);position:relative}R.numbered>.lines>p:before{content:counter(code);position:absolute;left:0;color:var(--n-6);font-size:var(--type-14)}R .k{color:var(--a1);font-weight:var(--name-weight)}R .s{color:var(--good)}R .c{color:var(--n-7)}R .n{color:var(--a2)}''')
# Build contract files and fixture data. CSS is written independently; samples supply markup and data only.
model={'card':'confetti','callout':'annual','chart-area':'annual','chart-bar':'confetti','chart-donut':'amethyst','chart-line':'amethyst'}
for k,(contract,rr) in roots.items():
 if k not in C:raise ValueError('Missing '+k)
 r=':is('+','.join('.'+x+'[data-el="roundrise-'+k+'"]' for x in rr)+')'
 common='''R{box-sizing:border-box;container-type:size;min-width:0;min-height:0;font-family:var(--font-body);font-size:var(--type-18);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--ink);anchor-scope:all}R *{box-sizing:border-box;min-width:0}R .fig{font-size:var(--type-48);font-family:var(--font-display);font-weight:var(--figure-weight);line-height:var(--figure-line);letter-spacing:var(--figure-track)}R .fig small{font-size:var(--type-24);font-weight:var(--name-weight)}R .name{font-size:var(--type-28);font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track);overflow-wrap:anywhere}R .note{font-size:var(--type-18);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--n-7);overflow-wrap:anywhere}R .kick{font-size:var(--type-16);font-weight:var(--label-weight);line-height:var(--label-line);letter-spacing:var(--label-track);color:var(--a1)}R .icon{display:inline-block;width:32px;height:32px;flex:none}R.on .note,R.on .kick{color:inherit}'''
 responsive='''@container (max-width:600px){R .name{font-size:var(--type-22)}R .fig{font-size:var(--type-36)}R .note{font-size:var(--type-16)}R .kick{font-size:var(--type-14)}R .parts{gap:var(--gap-sm)}R h2{font-size:var(--type-36)}R.big h2{font-size:var(--type-48)}R p{font-size:var(--type-20)}}@container (max-width:360px){R .name{font-size:var(--type-18)}R .fig{font-size:var(--type-28)}R .fig small{font-size:var(--type-16)}R .note{font-size:var(--type-14)}R .kick{display:none}R h2{font-size:var(--type-28)}R.big h2{font-size:var(--type-36)}R p{font-size:var(--type-16)}}@container (max-height:180px){R .name{font-size:var(--type-18)}R .fig{font-size:var(--type-28)}R .note{font-size:var(--type-14)}R .kick{display:none}R .mark{width:36px;height:36px}R .mark .icon{width:20px;height:20px}}'''
 write(B/f'elements/{k}/element.css',(common+C[k]+responsive).replace('R',r))
 write(B/f'elements/{k}/element.json',json.dumps({'schema':'rhetis.design-library-element-source/1','contract':contract,'registrations':{},'tokenDefaults':{}},indent=2))
 write(B/f'elements/{k}/description.md',f'The {k} composition translates Roundrise’s open presentation rhythm into its semantic contract. Rounded surfaces, circular or capsule markers, restrained hairlines and ranked bold figures keep the family consistent. Container steps reduce type before secondary copy, while the main name and figure remain visible. Accent roles are supplied entirely by the active palette.')
 sample=model.get(k,'annual');fs=list((REF/f'samples/{sample}/elements/{k}/fixtures').glob('*.html'))
 for f in fs:
  st=f.read_text();st=re.sub(r'data-el="(?:annual|confetti|amethyst)-', 'data-el="roundrise-',st)
  write(B/f'elements/{k}/fixtures/{f.name}',st)
 if len(fs)<2:
  st=(B/f'elements/{k}/fixtures/{fs[0].name}').read_text();st=st.replace('고객','핵심 고객').replace('매출','신규 사업 매출').replace('성장','지속 가능한 성장')
  write(B/f'elements/{k}/fixtures/extended.html',st)
print(len(C),'elements created')
